def is_magical(n):
    digits = str(n)
    product_sum = 0
    for i in range(1, 1 << len(digits)):
        product = 1
        for j in range(len(digits)):
            if i & (1 << j):
                product *= int(digits[j])
        product_sum += product
    return product_sum % 2 == 0

def find_kth_magical_number(K):
    count = 0
    num = 0
    while count < K:
        if is_magical(num):
            count += 1
        if count < K:
            num += 1
    return num

def main():
    T = int(input())
    results = []
    for _ in range(T):
        K = int(input())
        results.append(find_kth_magical_number(K))
    for result in results:
        print(result)

if __name__ == "__main__":
    main()
